if currentValue.value and not previousValue.value:

    logger = system.util.getLogger("PLC_ACK")

    try:
        # Get the corresponding Active_0 tag path
        activeTag = str(tagPath).replace("Acknowledged_0", "Active_0")

        # Convert tag path to alarm source format
        provider, tag = activeTag.split("]", 1)
        provider = provider.replace("[", "")

        alarmSource = "prov:%s:/tag:%s:/alm:Alarm" % (
            provider,
            tag.lstrip("/")
        )

        # Query all active, unacknowledged alarms
        alarms = system.alarm.queryStatus(state=["ActiveUnacked"])

        eventIds = []

        for alarm in alarms:
            if str(alarm.getSource()) == alarmSource:
                eventIds.append(str(alarm.getId()))

        if eventIds:

            logger.info("Acknowledging Alarm(s): {}".format(eventIds))

            system.alarm.acknowledge(
                eventIds,
                "Acknowledged from PLC",
                "PLC"
            )

            logger.info("Alarm acknowledged successfully.")

        else:
            logger.warn("No matching active unacknowledged alarm found.")

    except Exception as e:
        logger.error("Error acknowledging alarm: {}".format(e))

