tags.expression:
if(
    {[.]Active},

    concat(
        if(floor(dateDiff({[.]TimestampActive}, now(), "second")/86400) > 0,
            toStr(floor(dateDiff({[.]TimestampActive}, now(), "second")/86400)) + "d ",
            ""
        ),
        toStr(floor((dateDiff({[.]TimestampActive}, now(), "second") % 86400)/3600)) + "h ",
        toStr(floor((dateDiff({[.]TimestampActive}, now(), "second") % 3600)/60)) + "m ",
        toStr(dateDiff({[.]TimestampActive}, now(), "second") % 60) + "s"
    ),

    concat(
        if(floor(dateDiff({[.]TimestampActive}, {[.]TimestampReset}, "second")/86400) > 0,
            toStr(floor(dateDiff({[.]TimestampActive}, {[.]TimestampReset}, "second")/86400)) + "d ",
            ""
        ),
        toStr(floor((dateDiff({[.]TimestampActive}, {[.]TimestampReset}, "second") % 86400)/3600)) + "h ",
        toStr(floor((dateDiff({[.]TimestampActive}, {[.]TimestampReset}, "second") % 3600)/60)) + "m ",
        toStr(dateDiff({[.]TimestampActive}, {[.]TimestampReset}, "second") % 60) + "s"
    )
)
